import csv

for fname in ["ae_ip_termination.csv", "ae_ip_termination_by_month.csv"]:
    print("="*25, fname)
    with open(fname) as f:
        rows = list(csv.reader(f))
    print("rows:", len(rows), "| header:", rows[0] if rows else None)
    for r in rows[:80]:
        print(r)
    if len(rows) > 80:
        print("... truncated; showing last 20 ...")
        for r in rows[-20:]:
            print(r)
